extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var gv_obj: Object = instantiate_script("res://core/game_version.gd")
	if not check("script_loaded", gv_obj != null, "Lo script res://core/game_version.gd deve compilare e potersi istanziare"):
		return

	var current_ver: String = GameVersion.get_version_string()
	check("version_string", current_ver == "1.0.0", "get_version_string deve restituire '1.0.0' dalle impostazioni di progetto (restituito: '%s')" % current_ver)

	check("valid_semver_ok", GameVersion.is_valid_semver("1.0.0") == true, "is_valid_semver('1.0.0') deve restituire true")
	check("valid_semver_short", GameVersion.is_valid_semver("1.0") == false, "is_valid_semver('1.0') deve restituire false")
	check("valid_semver_prefix", GameVersion.is_valid_semver("v1.0.0") == false, "is_valid_semver('v1.0.0') con prefisso deve restituire false")

	var parsed: Dictionary = GameVersion.parse_semantic_version("2.4.11")
	check("parse_major", parsed.get("major", -1) == 2, "parse_semantic_version major errato")
	check("parse_minor", parsed.get("minor", -1) == 4, "parse_semantic_version minor errato")
	check("parse_patch", parsed.get("patch", -1) == 11, "parse_semantic_version patch errato")

	var desc_file := FileAccess.open("res://release/description.txt", FileAccess.READ)
	if check("desc_exists", desc_file != null, "Impossibile aprire release/description.txt"):
		var desc_text := desc_file.get_as_text()
		check("desc_len", desc_text.length() >= 50, "La descrizione deve contenere testo sufficiente (almeno 50 caratteri)")
		check("desc_content", desc_text.contains("Elena") and desc_text.contains("Marco") and desc_text.contains("Spazio"), "La descrizione deve menzionare Elena, Marco e il tasto Spazio")

	var cred_file := FileAccess.open("res://release/credits.txt", FileAccess.READ)
	if check("cred_exists", cred_file != null, "Impossibile aprire release/credits.txt"):
		var cred_text := cred_file.get_as_text()
		check("cred_godot", cred_text.contains("Godot") and cred_text.contains("MIT"), "I crediti devono citare Godot Engine e la licenza MIT")

