extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var checker_obj: Object = instantiate_script("res://release/release_checker.gd")
	if not check("script_loaded", checker_obj != null, "Lo script res://release/release_checker.gd deve compilare senza errori"):
		return

	var valid_web: bool = ReleaseChecker.check_web_archive_name("storie_v1.0.0_web.zip")
	check("web_name_valid", valid_web, "check_web_archive_name deve accettare storie_v1.0.0_web.zip")

	var invalid_web_1: bool = ReleaseChecker.check_web_archive_name("storie_web.zip")
	check("web_name_inv_1", not invalid_web_1, "check_web_archive_name deve rifiutare un archivio senza versione semantica")

	var invalid_web_2: bool = ReleaseChecker.check_web_archive_name("gioco_v1.0.0_web.zip")
	check("web_name_inv_2", not invalid_web_2, "check_web_archive_name deve richiedere il prefisso 'storie_v'")

	var manifest_res: Dictionary = ReleaseChecker.check_manifest("res://release/release_manifest.json")
	check("manifest_ok", manifest_res.get("valid", false) == true, "check_manifest deve confermare la validità di release_manifest.json")

	var missing_res: Dictionary = ReleaseChecker.check_manifest("res://release/inesistente.json")
	check("manifest_missing", missing_res.get("valid", true) == false, "check_manifest deve segnalare errore se il file non esiste")

	var audit: Dictionary = ReleaseChecker.audit_release_package("res://release/")
	var checklist: Dictionary = audit.get("checklist", {})
	check("chk_manifest", checklist.get("manifest", false) == true, "La checklist deve convalidare il manifesto")
	check("chk_desc", checklist.get("description", false) == true, "La checklist deve convalidare description.txt")
	check("chk_credits", checklist.get("credits", false) == true, "La checklist deve convalidare credits.txt")
	check("chk_version", checklist.get("version_match", false) == true, "La checklist deve convalidare la corrispondenza di versione con il progetto")
	check("chk_web", checklist.get("web_archive_name", false) == true, "La checklist deve convalidare il nome dell'archivio Web")
	check("audit_ready", audit.get("ready_to_publish", false) == true, "ready_to_publish deve risultare true quando tutti i requisiti sono soddisfatti")

